  @override
  String get legalDataConsentCountryUSBody =>
      'États-Unis : les utilisateurs du CCPA/CPRA ont le droit de refuser la vente ou le partage d\'informations personnelles. Umbrella ne vend pas d’informations personnelles. Le partage de données avec des fournisseurs d\'IA pour la prestation de services ne constitue pas une « vente » en vertu du CCPA. Les informations personnelles sensibles ne sont pas partagées avec les fournisseurs d’IA sans consentement explicite.';

