  @override
  String get legalDataConsentNeverUsedBody =>
      'Les données suivantes ne sont en aucun cas utilisées pour la formation à l\'IA, y compris avec opt-in : (a) les informations de facturation et les données de carte de paiement ; (b) les noms complets des clients, les numéros d\'identification nationaux, les numéros de passeport ou les données biométriques sans anonymisation complète ; (c) les communications protégées par le secret professionnel, à moins que le titulaire du privilège ne fournisse un consentement écrit explicite ; (d) les données faisant l\'objet d\'une conservation légale ou d\'un litige actif ; (e) les données de santé ou médicales ; (f) les données des utilisateurs de moins de 18 ans.';

