  @override
  String get legalDisclaimerAINotLawyerBody =>
      'Les systèmes d\'IA d\'Umbrella sont de grands modèles de langage formés sur des corpus juridiques généraux. Ils ne détiennent pas de certificat d’exercice, ne peuvent pas comparaître devant un tribunal, ne sont réglementés par aucun barreau ou barreau et n’ont aucune obligation de diligence envers vous comme le ferait un avocat. Les résultats de l\'IA peuvent : contenir des erreurs factuelles ou des hallucinations ; omettre des considérations importantes liées à vos faits spécifiques ; citer des lois ou des affaires qui ont été modifiées, abrogées ou annulées ; ne tiennent pas compte des récents changements législatifs ; et mal interpréter des questions juridiques complexes ou ambiguës. Vous devez traiter chaque sortie de l’IA comme un point de départ pour une enquête et non comme une réponse finale.';

  @override
  String get legalDisclaimerAINotLawyerHeading => '3. L’IA n’est pas un avocat';

  @override
  String get legalDisclaimerCitationBody =>
      'Lorsque Umbrella cite une loi, un règlement, une règle ou une décision judiciaire, vous devez vérifier de manière indépendante : (a) que la source citée existe ; (b) que la citation est exacte (section, sous-section et année) ; (c) que la source est actuellement en vigueur et n\'a pas été modifiée ou abrogée ; (d) que le texte cité reflète fidèlement la source. Les erreurs de citation de l’IA – y compris les citations fabriquées – sont une limitation connue de tous les systèmes d’IA actuels. Ne vous fiez jamais à une citation dans une procédure judiciaire, un conseil ou un dépôt sans vérification indépendante.';

  @override
  String get legalDisclaimerCitationHeading => 'Règle de citation de l\'IA';

  @override
  String get legalDisclaimerJurisdictionBody =>
      'Inde : l\'analyse de l\'IA est basée sur la législation centrale, les lois de l\'État lorsque cela est spécifié et les décisions judiciaires publiées. Il ne tient pas compte de la pratique au niveau des tribunaux de district, des coutumes des barreaux locaux ou des règles de procédure non codifiées. États-Unis : l’analyse de l’IA est basée sur la loi fédérale et sur certaines lois d’État. L’analyse juridique américaine ne remplace pas l’intervention d’un avocat agréé dans un État donné. Non disponible pour les questions d\'immigration, de défense pénale ou fiscales sans examen vérifié par un avocat. Kenya : l\'analyse s\'appuie sur les lois kenyanes, la législation subsidiaire et les décisions publiées de la Haute Cour et de la Cour d\'appel. Il ne tient pas compte du droit coutumier, des variations des tribunaux d\'instance ou des décisions non publiées. Royaume-Uni : l’analyse couvre le droit anglais et gallois. Le droit écossais, le droit nord-irlandais et les matières décentralisées peuvent différer considérablement ; demander des conseils spécifiques à votre juridiction.';

  @override
