  @override
  String get legalTermsDefinitionsBody =>
      '« Plateforme » désigne parapluie.okaylegal.ai et toutes les applications, API et services associés. « Utilisateur Consommateur » désigne une personne physique utilisant la plateforme pour comprendre sa propre situation juridique. « Utilisateur avocat » désigne un professionnel du droit agréé utilisant les fonctionnalités de Lawyer OS. « Locataire » désigne un cabinet d\'avocats ou une organisation disposant d\'un abonnement ferme. « Sortie IA » désigne tout texte, analyse, brouillon ou recommandation généré par les systèmes d\'IA d\'Umbrella. « Affaire » désigne une affaire juridique ou une transaction gérée via Lawyer OS. « DVTech Ventures » ou « nous » désigne l\'opérateur de la plateforme.';

  @override
  String get legalTermsDefinitionsHeading => '2. Définitions';

  @override
  String get legalTermsDescription =>
      'Règles d\'utilisation des plateformes Umbrella pour les consommateurs et les avocats.';

  @override
  String get legalTermsDisputeBody =>
      'Utilisateurs indiens : ces conditions sont régies par les lois de l\'Inde ; les différends seront résolus par arbitrage exécutoire en vertu de la loi sur l\'arbitrage et la conciliation de 1996, siégeant à Bangalore. Utilisateurs des États-Unis : les litiges seront résolus par arbitrage exécutoire conformément aux règles d\'arbitrage commercial de l\'AAA, siégeant dans le Delaware ; la renonciation au recours collectif s’applique. Utilisateurs du Kenya : ces conditions sont régies par les lois du Kenya ; les différends seront résolus conformément aux règles du Centre d’arbitrage international de Nairobi (NCIA). Utilisateurs du Royaume-Uni : les présentes Conditions sont régies par le droit anglais ; les litiges seront soumis à la compétence exclusive des tribunaux d’Angleterre et du Pays de Galles. Dans tous les cas, rien ne vous empêche de demander en urgence une injonction auprès d’un tribunal compétent.';

  @override
  String get legalTermsDisputeHeading =>
      '18. Règlement des litiges et loi applicable';

  @override
  String get legalTermsIPContentBody =>
      'Vous conservez la propriété de tout le contenu que vous soumettez à la plateforme. En soumettant du contenu, vous accordez à DVTech Ventures une licence mondiale, libre de droits et non exclusive pour traiter, stocker et afficher votre contenu uniquement pour fournir les services. Cette licence ne s\'étend pas à la formation en IA, sauf si vous y souscrivez en vertu de la politique de consentement aux données et à l\'IA.';

  @override
