      'DVTech Ventures détient tous les droits sur la plate-forme Umbrella, la marque, les modèles d\'IA sous-jacents et la technologie. Vous bénéficiez d\'une licence limitée, non exclusive et non transférable pour utiliser la plateforme pendant la durée de votre abonnement.';

  @override
  String get legalTermsIndemnityBody =>
      'Vous acceptez d\'indemniser, de défendre et de dégager DVTech Ventures et ses dirigeants, administrateurs, employés et agents de toute responsabilité contre toute réclamation, dommage, perte et dépense (y compris les frais juridiques raisonnables) découlant de : (a) votre utilisation de la plateforme en violation des présentes Conditions ; (b) votre violation de toute loi applicable ; (c) le contenu que vous soumettez qui porte atteinte aux droits d\'un tiers ; (d) les conseils juridiques ou les services que vous fournissez à vos clients en utilisant la plateforme.';

  @override
  String get legalTermsIndemnityHeading => '17. Indemnisation';

  @override
  String get legalTermsLawyerUsersBody =>
      'Les utilisateurs avocats sont des professionnels indépendants agréés. En utilisant Lawyer OS, vous confirmez que vous détenez un certificat d\'exercice valide dans votre juridiction et que vous utiliserez la plateforme conformément aux règles de déontologie et aux règlements du barreau applicables. Vous restez seul responsable de la qualité et de la légalité de tous les travaux juridiques et conseils que vous fournissez à vos clients. Umbrella fournit des outils – il ne supervise ni ne garantit la conduite professionnelle des utilisateurs avocats.';

