      'Vous ne devez pas : (a) vous faire passer pour un avocat, un juge ou un représentant du gouvernement ; (b) utiliser les résultats de l\'IA comme conseil juridique formel à des tiers sans examen par un avocat ; (c) soumettre du contenu illégal, diffamatoire ou frauduleux ; (d) tenter de faire de l\'ingénierie inverse, de gratter ou d\'extraire les modèles d\'IA ou les données de formation sous-jacents ; (e) revendre ou concéder en sous-licence l\'accès à la plateforme sans consentement écrit ; (f) utiliser la plateforme d\'une manière qui viole la loi applicable, y compris les règles de protection des données, de protection des consommateurs et de la profession juridique ; (g) soumettre du contenu qui enfreint les droits de propriété intellectuelle de tiers.';

